  expect(Range(0, 10).filter($ => true).butLast().toArray()).toEqual([
    0, 1, 2, 3, 4, 5, 6, 7, 8,
  ]);
  expect(Range(0, 10).filter($ => true).slice(-2, 10).toArray()).toEqual([
    8, 9,
  ]);
  expect(Range(0, 10).filter($ => true).slice(0, -2).toArray()).toEqual([
    0, 1, 2, 3, 4, 5, 6, 7,
  ]);
  expect(Range(0, 10).slice(-2).toArray()).toEqual([8, 9]);
  expect(Range(0, 10).filter($ => true).takeLast(2).toArray()).toEqual([8, 9]);
  expect(Range(0, 10).filter($ => true).skipLast(2).toArray()).toEqual([
    0, 1, 2, 3, 4, 5, 6, 7,
  ]);
});
